/**
 * Generates the CertificateRegistry ABI modules from the Hardhat artifact —
 * one source of truth, two consumers:
 *
 *   backend/services/certificateRegistryABI.js   (ESM export, bundled on Vercel)
 *   frontend/src/utils/contractABI.js            (CRA import)
 *
 * Run after `npx hardhat compile`:  node scripts/generateAbi.js
 * The generated files are committed — deployments never depend on artifacts/
 * being present (Vercel only bundles backend/**).
 */
const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, "..");
const artifactPath = path.join(root, "artifacts", "contracts", "CertificateRegistry.sol", "CertificateRegistry.json");

if (!fs.existsSync(artifactPath)) {
  console.error("Artifact missing — run `npx hardhat compile` first.");
  process.exit(1);
}

const artifact = JSON.parse(fs.readFileSync(artifactPath, "utf8"));
const abiJson = JSON.stringify(artifact.abi, null, 2);

const header = `// AUTO-GENERATED by scripts/generateAbi.js from the Hardhat artifact.\n// Do not edit by hand — re-run the script after contract changes.\n`;

const backendOut = path.join(root, "backend", "services", "certificateRegistryABI.js");
fs.writeFileSync(backendOut, `${header}export const CERTIFICATE_REGISTRY_ABI = ${abiJson};\n`);

const frontendOut = path.join(root, "frontend", "src", "utils", "contractABI.js");
fs.mkdirSync(path.dirname(frontendOut), { recursive: true });
fs.writeFileSync(frontendOut, `${header}export const CERTIFICATE_REGISTRY_ABI = ${abiJson};\nexport default CERTIFICATE_REGISTRY_ABI;\n`);

console.log(`ABI written: ${backendOut}`);
console.log(`ABI written: ${frontendOut}`);
console.log(`Entries: ${artifact.abi.length}`);